function Nav(){var sidenav=document.getElementById("mySidenav"),marginRight=window.getComputedStyle(sidenav).getPropertyValue("margin-right"),btn=document.getElementById("btn-sidebar");"-350px"===marginRight||""===marginRight?(sidenav.style.marginRight="0px",btn.className=btn.className.replace("btn-sidebar-light","btn-sidebar-dark")):(sidenav.style.marginRight="-350px",btn.className=btn.className.replace("btn-sidebar-dark","btn-sidebar-light"))}